(()=>{const t=[["days",86400],["hours",3600],["minutes",60],["seconds",1]],e=(e,n)=>{let o=Math.max(0,Math.floor((n-Date.now())/1e3));return 0===o?(e.classList.add("is-expired"),!1):(t.forEach(([t,n])=>{const a=Math.floor(o/n);o-=a*n;const r=e.querySelector(`[data-countdown-unit="${t}"]`);r&&(r.textContent="days"===t?String(a):String(a).padStart(2,"0"))}),!0)},n=t=>{const n=Date.parse(t.dataset.countdownTo);if(Number.isNaN(n))return;if(!e(t,n))return;const o=setInterval(()=>{e(t,n)||clearInterval(o)},1e3)},o=()=>document.querySelectorAll("[data-countdown-to]").forEach(n);"loading"===document.readyState?document.addEventListener("DOMContentLoaded",o):o()})();